window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-70179fb886c56683"]={"versions": [{"id": "FIG-70179fb886c56683", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Metamodellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) im AUTOSAR-System-Template. Es spezifiziert die Struktur der CAN-spezifischen Konfigurationseigenschaften (<code>CanGlobalTimeDomainProps</code>) innerhalb einer <code>GlobalTimeDomain</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> (spezialisiert <code>FibexElement</code>): Zentrales Element einer globalen Zeitdomäne. Enthält die Attribute <code>debounceTime: TimeValue [0..1]</code>, <code>domainId: PositiveInteger</code>, <code>syncLossThreshold: TimeValue [0..1]</code> sowie <code>syncLossTimeout: TimeValue [0..1]</code>.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Selbstassoziation <code>+offsetTimeDomain</code> mit Multiplizität <code>0..1</code> zur Modellierung hierarchischer oder versetzter Zeitdomänen.\n</li><li>Besitzt eine gerichtete Selbstassoziation <code>+subDomain</code> mit Multiplizität <code>0..*</code> zur Anbindung untergeordneter Zeitdomänen.\n</li><li>Komponiert über die Rolle <code>+globalTimeDomainProps</code> mit Multiplizität <code>0..1</code> die abstrakte Basisklasse <code>AbstractGlobalTimeDomainProps</code>.\n</li></ul>\n</li><li><code>AbstractGlobalTimeDomainProps</code> (kursiv / abstrakt): Abstrakte Basisklasse für busspezifische Eigenschaften einer Zeitdomäne.\n</li><li><code>CanGlobalTimeDomainProps</code>: Spezialisiert <code>AbstractGlobalTimeDomainProps</code> via Generalisierung. Definiert geordnete Listen für CAN-spezifische GTS-Data-IDs:\n<ul class=\"fig-list\"><li><code>+fupDataIDList: PositiveInteger [0..16] {ordered}</code> (Follow-Up Data IDs)\n</li><li><code>+ofnsDataIDList: PositiveInteger [0..16] {ordered}</code> (Offset Not Sync Data IDs)\n</li><li><code>+ofsDataIDList: PositiveInteger [0..16] {ordered}</code> (Offset Sync Data IDs)\n</li><li><code>+syncDataIDList: PositiveInteger [0..16] {ordered}</code> (Synchronization Data IDs)\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als strukturelles Metamodell-Klassendiagramm bildet die Darstellung keine dynamischen Abläufe oder Nachrichtensequenzen ab. Sie definiert die statischen Konfigurationsstrukturen für die Laufzeitsynchronisation von Zeitnachrichten (SYNC, FUP, OFS, OFNS) über CAN-Netzwerke, einschließlich Entprellung (<code>debounceTime</code>) und Timeout-Überwachung (<code>syncLossTimeout</code>, <code>syncLossThreshold</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Assoziationen sind für Systembeschreibungen normativ bindend:</p>\n<ul class=\"fig-list\"><li>Eine CAN-Zeitdomäne darf maximal eine <code>CanGlobalTimeDomainProps</code>-Instanz aggregieren.\n</li><li>Die vier Data-ID-Listen in <code>CanGlobalTimeDomainProps</code> sind strikt geordnet (<code>{ordered}</code>) und auf jeweils bis zu 16 Identifier (<code>[0..16]</code>) begrenzt; sie dienen der Validierung und Zuordnung empfangener CAN-Zeitsynchronisations-Botschaften.\n</li><li>Zeitwerte (<code>TimeValue</code>) und Identifikatoren (<code>domainId</code>) definieren die Parametrierung der Zeitbasis und der Ausfallkriterien.\n</li></ul>"}, {"id": "FIG-f0e1bcfd587df817", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Metamodellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) im AUTOSAR-System-Template. Es spezifiziert die Struktur der CAN-spezifischen Konfigurationseigenschaften (<code>CanGlobalTimeDomainProps</code>) innerhalb einer <code>GlobalTimeDomain</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> (spezialisiert <code>FibexElement</code>): Zentrales Element einer globalen Zeitdomäne. Enthält die Attribute <code>debounceTime: TimeValue [0..1]</code>, <code>domainId: PositiveInteger</code> sowie <code>syncLossTimeout: TimeValue [0..1]</code>.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Selbstassoziation <code>+offsetTimeDomain</code> mit Multiplizität <code>0..1</code>.\n</li><li>Besitzt eine variabilitätsfähige gerichtete Selbstassoziation <code>+globalTimeSubDomain</code> mit Multiplizität <code>0..*</code>, annotiert mit <code>«atpVariation»</code>.\n</li><li>Komponiert über die variabilitätsfähige Rolle <code>+globalTimeDomainProperty</code> mit Multiplizität <code>0..1</code> (<code>«atpVariation»</code>) die abstrakte Basisklasse <code>AbstractGlobalTimeDomainProps</code>.\n</li></ul>\n</li><li><code>AbstractGlobalTimeDomainProps</code> (abstrakt): Abstrakte Basisklasse für busspezifische Eigenschaften einer Zeitdomäne.\n</li><li><code>CanGlobalTimeDomainProps</code>: Spezialisiert <code>AbstractGlobalTimeDomainProps</code>. Definiert geordnete Listen für CAN-spezifische GTS-Data-IDs:\n<ul class=\"fig-list\"><li><code>+fupDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+ofnsDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+ofsDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+syncDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als strukturelles Metamodell-Klassendiagramm bildet die Darstellung keine dynamischen Abläufe oder Nachrichtensequenzen ab. Sie definiert die statischen Konfigurationsstrukturen für die Laufzeitsynchronisation von Zeitnachrichten (SYNC, FUP, OFS, OFNS) über CAN-Netzwerke, einschließlich Entprellung (<code>debounceTime</code>) und Timeout-Überwachung (<code>syncLossTimeout</code>, <code>syncLossThreshold</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Assoziationen sind für Systembeschreibungen normativ bindend:</p>\n<ul class=\"fig-list\"><li>Die Anbindung von <code>AbstractGlobalTimeDomainProps</code> (<code>+globalTimeDomainProperty</code>) sowie von Subdomänen (<code>+globalTimeSubDomain</code>) unterliegt der AUTOSAR-Variantenbildung (<code>«atpVariation»</code>), womit diese Elemente abhängig von Systemkonstanten und Post-Build-/Binding-Zeitpunkten variiert werden können.\n</li><li>Die Data-ID-Listen sind strikt geordnet (<code>{ordered}</code>) und auf maximal 16 Werte limitiert.\n</li><li><code>syncLossThreshold</code> ist in dieser Modellierung nicht mehr Teil von <code>GlobalTimeDomain</code>.\n</li></ul>"}, {"id": "FIG-547a8063ef0a4070", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Metamodellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) im AUTOSAR-System-Template. Es spezifiziert die Struktur der CAN-spezifischen Konfigurationseigenschaften (<code>CanGlobalTimeDomainProps</code>) innerhalb einer <code>GlobalTimeDomain</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> (spezialisiert <code>FibexElement</code>): Zentrales Element einer globalen Zeitdomäne. Enthält die Attribute <code>debounceTime: TimeValue [0..1]</code>, <code>domainId: PositiveInteger</code> sowie <code>syncLossTimeout: TimeValue [0..1]</code>.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Selbstassoziation <code>+offsetTimeDomain</code> mit Multiplizität <code>0..1</code>.\n</li><li>Besitzt eine variabilitätsfähige gerichtete Selbstassoziation <code>+globalTimeSubDomain</code> mit Multiplizität <code>0..*</code>, annotiert mit <code>«atpVariation»</code>.\n</li><li>Komponiert über die variabilitätsfähige Rolle <code>+globalTimeDomainProperty</code> mit Multiplizität <code>0..1</code> (<code>«atpVariation»</code>) die abstrakte Basisklasse <code>AbstractGlobalTimeDomainProps</code>.\n</li></ul>\n</li><li><code>AbstractGlobalTimeDomainProps</code> (abstrakt): Abstrakte Basisklasse für busspezifische Eigenschaften einer Zeitdomäne.\n</li><li><code>CanGlobalTimeDomainProps</code>: Spezialisiert <code>AbstractGlobalTimeDomainProps</code>. Definiert geordnete Listen für CAN-spezifische GTS-Data-IDs:\n<ul class=\"fig-list\"><li><code>+fupDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+ofnsDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+ofsDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+syncDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als strukturelles Metamodell-Klassendiagramm bildet die Darstellung keine dynamischen Abläufe oder Nachrichtensequenzen ab. Sie definiert die statischen Konfigurationsstrukturen für die Laufzeitsynchronisation von Zeitnachrichten (SYNC, FUP, OFS, OFNS) über CAN-Netzwerke, einschließlich Entprellung (<code>debounceTime</code>) und Timeout-Überwachung (<code>syncLossTimeout</code>, <code>syncLossThreshold</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Assoziationen sind für Systembeschreibungen normativ bindend:</p>\n<ul class=\"fig-list\"><li>Die Anbindung von <code>AbstractGlobalTimeDomainProps</code> (<code>+globalTimeDomainProperty</code>) sowie von Subdomänen (<code>+globalTimeSubDomain</code>) unterliegt der AUTOSAR-Variantenbildung (<code>«atpVariation»</code>), womit diese Elemente abhängig von Systemkonstanten und Post-Build-/Binding-Zeitpunkten variiert werden können.\n</li><li>Die Data-ID-Listen sind strikt geordnet (<code>{ordered}</code>) und auf maximal 16 Werte limitiert.\n</li><li><code>syncLossThreshold</code> ist in dieser Modellierung nicht mehr Teil von <code>GlobalTimeDomain</code>.\n</li></ul>"}, {"id": "FIG-476442918a3844eb", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Metamodellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) im AUTOSAR-System-Template. Es spezifiziert die Struktur der CAN-spezifischen Konfigurationseigenschaften (<code>CanGlobalTimeDomainProps</code>) innerhalb einer <code>GlobalTimeDomain</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> (spezialisiert <code>FibexElement</code>): Enthält <code>debounceTime: TimeValue [0..1]</code>, <code>domainId: PositiveInteger</code> und <code>syncLossTimeout: TimeValue [0..1]</code>.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Selbstassoziation <code>+offsetTimeDomain</code> mit Multiplizität <code>0..1</code>.\n</li><li>Besitzt eine variabilitätsfähige Selbstassoziation <code>+globalTimeSubDomain</code> mit Multiplizität <code>0..*</code> (<code>«atpVariation»</code>).\n</li><li>Komponiert über <code>+globalTimeDomainProperty</code> mit Multiplizität <code>0..1</code> (<code>«atpVariation»</code>) die Klasse <code>AbstractGlobalTimeDomainProps</code>.\n</li><li>Komponiert über die Rolle <code>+networkSegmentId</code> mit Multiplizität <code>0..1</code> die Klasse <code>NetworkSegmentIdentification</code>.\n</li></ul>\n</li><li><code>NetworkSegmentIdentification</code>: Spezifiziert ein Netzwerksegment mit dem Attribut <code>+networkSegmentId: PositiveInteger [0..1]</code>.\n</li><li><code>AbstractGlobalTimeDomainProps</code> (abstrakt): Basisklasse für domänenspezifische Eigenschaften.\n</li><li><code>CanGlobalTimeDomainProps</code>: Spezialisiert <code>AbstractGlobalTimeDomainProps</code> und enthält:\n<ul class=\"fig-list\"><li><code>+fupDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+ofnsDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+ofsDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+syncDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als strukturelles Metamodell-Klassendiagramm bildet die Darstellung keine dynamischen Abläufe oder Nachrichtensequenzen ab. Sie definiert die statischen Konfigurationsstrukturen für die Laufzeitsynchronisation von Zeitnachrichten (SYNC, FUP, OFS, OFNS) über CAN-Netzwerke, einschließlich Entprellung (<code>debounceTime</code>) und Timeout-Überwachung (<code>syncLossTimeout</code>, <code>syncLossThreshold</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Beziehungen sind normativ bindend:</p>\n<ul class=\"fig-list\"><li>Eine Zeitdomäne kann über <code>NetworkSegmentIdentification</code> explizit einem Netzwerksegment (<code>networkSegmentId</code>) zugeordnet werden.\n</li><li>Die Variabilität (<code>«atpVariation»</code>) erlaubt bedingte Konfigurationen für <code>globalTimeDomainProperty</code> und <code>globalTimeSubDomain</code>.\n</li><li>Die CAN-spezifischen Listen bleiben auf bis zu 16 geordnete Ganzzahlen beschränkt.\n</li></ul>"}, {"id": "FIG-6c5ce82ff231e827", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Metamodellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) im AUTOSAR-System-Template. Es spezifiziert die Struktur der CAN-spezifischen Konfigurationseigenschaften (<code>CanGlobalTimeDomainProps</code>) innerhalb einer <code>GlobalTimeDomain</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> (spezialisiert <code>FibexElement</code>): Enthält <code>debounceTime: TimeValue [0..1]</code>, <code>domainId: PositiveInteger</code> und <code>syncLossTimeout: TimeValue [0..1]</code>.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Selbstassoziation <code>+offsetTimeDomain</code> mit Multiplizität <code>0..1</code>.\n</li><li>Besitzt eine variabilitätsfähige und aufteilbare Selbstassoziation <code>+globalTimeSubDomain</code> mit Multiplizität <code>0..*</code> (<code>«atpVariation,atpSplitable»</code>).\n</li><li>Komponiert über <code>+globalTimeDomainProperty</code> mit Multiplizität <code>0..1</code> (<code>«atpVariation,atpSplitable»</code>) die Klasse <code>AbstractGlobalTimeDomainProps</code>.\n</li><li>Komponiert über <code>+networkSegmentId</code> mit Multiplizität <code>0..1</code> die Klasse <code>NetworkSegmentIdentification</code>.\n</li></ul>\n</li><li><code>NetworkSegmentIdentification</code>: Spezifiziert ein Netzwerksegment mit <code>+networkSegmentId: PositiveInteger [0..1]</code>.\n</li><li><code>AbstractGlobalTimeDomainProps</code> (abstrakt): Basisklasse für domänenspezifische Eigenschaften.\n</li><li><code>CanGlobalTimeDomainProps</code>: Spezialisiert <code>AbstractGlobalTimeDomainProps</code> und enthält:\n<ul class=\"fig-list\"><li><code>+fupDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+ofnsDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+ofsDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+syncDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als strukturelles Metamodell-Klassendiagramm bildet die Darstellung keine dynamischen Abläufe oder Nachrichtensequenzen ab. Sie definiert die statischen Konfigurationsstrukturen für die Laufzeitsynchronisation von Zeitnachrichten (SYNC, FUP, OFS, OFNS) über CAN-Netzwerke, einschließlich Entprellung (<code>debounceTime</code>) und Timeout-Überwachung (<code>syncLossTimeout</code>, <code>syncLossThreshold</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Beziehungen sind normativ bindend:</p>\n<ul class=\"fig-list\"><li>Die Rollen <code>globalTimeSubDomain</code> und <code>globalTimeDomainProperty</code> tragen den Stereotyp <code>«atpVariation,atpSplitable»</code>. Sie können somit im Rahmen des AUTOSAR-Modell-Splittings über mehrere Dateien oder ARXML-Fragmente aufgeteilt sowie variiert werden.\n</li><li>Zuordnung und Einschränkungen bezüglich <code>NetworkSegmentIdentification</code> und <code>CanGlobalTimeDomainProps</code> bleiben verbindlich.\n</li></ul>"}, {"id": "FIG-54e90da8e3bd05b4", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Metamodellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) im AUTOSAR-System-Template. Es spezifiziert die Struktur der CAN-spezifischen Konfigurationseigenschaften (<code>CanGlobalTimeDomainProps</code>) innerhalb einer <code>GlobalTimeDomain</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> (spezialisiert <code>FibexElement</code> und <code>UploadableDesignElement</code>): Enthält <code>debounceTime: TimeValue [0..1]</code>, <code>domainId: PositiveInteger [0..1]</code> und <code>syncLossTimeout: TimeValue [0..1]</code>.\n<ul class=\"fig-list\"><li>Besitzt eine gerichtete Selbstassoziation <code>+offsetTimeDomain</code> mit Multiplizität <code>0..1</code>.\n</li><li>Besitzt eine Selbstassoziation <code>+globalTimeSubDomain</code> mit Multiplizität <code>0..*</code> (<code>«atpVariation,atpSplitable»</code>).\n</li><li>Komponiert über <code>+globalTimeDomainProperty</code> mit Multiplizität <code>0..1</code> (<code>«atpVariation,atpSplitable»</code>) die Klasse <code>AbstractGlobalTimeDomainProps</code>.\n</li><li>Komponiert über <code>+networkSegmentId</code> mit Multiplizität <code>0..1</code> die Klasse <code>NetworkSegmentIdentification</code>.\n</li></ul>\n</li><li><code>NetworkSegmentIdentification</code>: Spezifiziert ein Netzwerksegment mit <code>+networkSegmentId: PositiveInteger [0..1]</code>.\n</li><li><code>AbstractGlobalTimeDomainProps</code> (abstrakt): Basisklasse für domänenspezifische Eigenschaften.\n</li><li><code>CanGlobalTimeDomainProps</code>: Spezialisiert <code>AbstractGlobalTimeDomainProps</code> und enthält:\n<ul class=\"fig-list\"><li><code>+fupDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+ofnsDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+ofsDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+syncDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als strukturelles Metamodell-Klassendiagramm bildet die Darstellung keine dynamischen Abläufe oder Nachrichtensequenzen ab. Sie definiert die statischen Konfigurationsstrukturen für die Laufzeitsynchronisation von Zeitnachrichten (SYNC, FUP, OFS, OFNS) über CAN-Netzwerke, einschließlich Entprellung (<code>debounceTime</code>) und Timeout-Überwachung (<code>syncLossTimeout</code>, <code>syncLossThreshold</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen und Beziehungen sind normativ bindend:</p>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> erbt als <code>UploadableDesignElement</code> die Eigenschaften für OTA-/Upload-Mechanismen im System-Design.\n</li><li>Das Attribut <code>domainId</code> ist optional (<code>[0..1]</code>), womit Zeitdomänen ohne feste numerische Domänenkennung modelliert werden können.\n</li><li>Modell-Splitting und Variabilität (<code>«atpVariation,atpSplitable»</code>) gelten weiterhin für <code>globalTimeDomainProperty</code> und <code>globalTimeSubDomain</code>.\n</li></ul>"}, {"id": "FIG-7ee3e6dec7f699b0", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Metamodellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) im AUTOSAR-System-Template. Es spezifiziert die Struktur der CAN-spezifischen Konfigurationseigenschaften (<code>CanGlobalTimeDomainProps</code>) innerhalb einer <code>GlobalTimeDomain</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> (spezialisiert <code>FibexElement</code> und <code>UploadableDesignElement</code>): Enthält:\n<ul class=\"fig-list\"><li><code>+debounceTime: TimeValue [0..1]</code>\n</li><li><code>+domainId: PositiveInteger [0..1]</code>\n</li><li><code>+icvFreshnessValueId: PositiveInteger [0..1]</code>\n</li><li><code>+maxProgressionMismatchThreshold: TimeValue [0..1]</code>\n</li><li><code>+syncLossTimeout: TimeValue [0..1]</code>\n</li><li>Besitzt eine Selbstassoziation <code>+globalTimeSubDomain</code> mit Multiplizität <code>0..*</code> (<code>«atpVariation,atpSplitable»</code>).\n</li><li>Komponiert über <code>+globalTimeDomainProperty</code> mit Multiplizität <code>0..1</code> (<code>«atpVariation,atpSplitable»</code>) die Klasse <code>AbstractGlobalTimeDomainProps</code>.\n</li><li>Komponiert über <code>+networkSegmentId</code> mit Multiplizität <code>0..1</code> die Klasse <code>NetworkSegmentIdentification</code>.\n</li></ul>\n</li><li><code>NetworkSegmentIdentification</code>: Spezifiziert ein Netzwerksegment mit <code>+networkSegmentId: PositiveInteger [0..1]</code>.\n</li><li><code>AbstractGlobalTimeDomainProps</code> (abstrakt): Basisklasse für domänenspezifische Eigenschaften.\n</li><li><code>CanGlobalTimeDomainProps</code>: Spezialisiert <code>AbstractGlobalTimeDomainProps</code> und enthält:\n<ul class=\"fig-list\"><li><code>+fupDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+ofnsDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+ofsDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+syncDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als strukturelles Metamodell-Klassendiagramm bildet die Darstellung keine dynamischen Abläufe oder Nachrichtensequenzen ab. Sie definiert die statischen Konfigurationsstrukturen für die Laufzeitsynchronisation von Zeitnachrichten (SYNC, FUP, OFS, OFNS) über CAN-Netzwerke, einschließlich Entprellung (<code>debounceTime</code>) und Timeout-Überwachung (<code>syncLossTimeout</code>, <code>syncLossThreshold</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation ist normativ verbindlich:</p>\n<ul class=\"fig-list\"><li>Die Absicherung und Plausibilisierung der Zeitinformation wird um Sicherheits- und Konsistenzparameter erweitert: <code>icvFreshnessValueId</code> für die Integritäts- und Frischeprüfung (SecOC / ICV) sowie <code>maxProgressionMismatchThreshold</code> für Schwellenwerte unzulässiger zeitlicher Abweichungen/Sprünge.\n</li><li>Eine Modellierung von Offset-Domänen über eine eigenständige Assoziation <code>offsetTimeDomain</code> ist an <code>GlobalTimeDomain</code> nicht mehr vorgesehen.\n</li></ul>"}, {"id": "FIG-d93ebfa1fdf11536", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur statischen Metamodellierung der globalen Zeitsynchronisation (Global Time Synchronization, GTS) im AUTOSAR-System-Template. Es spezifiziert die Struktur der CAN-spezifischen Konfigurationseigenschaften (<code>CanGlobalTimeDomainProps</code>) innerhalb einer <code>GlobalTimeDomain</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Klassen, Attribute und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>GlobalTimeDomain</code> (spezialisiert <code>FibexElement</code> und <code>UploadableDesignElement</code>): Enthält:\n<ul class=\"fig-list\"><li><code>+debounceTime: TimeValue [0..1]</code>\n</li><li><code>+icvFreshnessValueId: PositiveInteger [0..1]</code>\n</li><li><code>+maxProgressionMismatchThreshold: TimeValue [0..1]</code>\n</li><li><code>+syncLossTimeout: TimeValue [0..1]</code>\n</li><li><code>«atpVariation» +domainId: PositiveInteger [0..1]</code>\n</li><li>Besitzt eine Selbstassoziation <code>+globalTimeSubDomain</code> mit Multiplizität <code>0..*</code> (<code>«atpVariation,atpSplitable»</code>).\n</li><li>Komponiert über <code>+globalTimeDomainProperty</code> mit Multiplizität <code>0..1</code> (<code>«atpVariation,atpSplitable»</code>) die Klasse <code>AbstractGlobalTimeDomainProps</code>.\n</li><li>Komponiert über <code>+networkSegmentId</code> mit Multiplizität <code>0..1</code> die Klasse <code>NetworkSegmentIdentification</code>.\n</li></ul>\n</li><li><code>NetworkSegmentIdentification</code>: Spezifiziert ein Netzwerksegment mit <code>+networkSegmentId: PositiveInteger [0..1]</code>.\n</li><li><code>AbstractGlobalTimeDomainProps</code> (abstrakt): Basisklasse für domänenspezifische Eigenschaften.\n</li><li><code>CanGlobalTimeDomainProps</code>: Spezialisiert <code>AbstractGlobalTimeDomainProps</code> und enthält:\n<ul class=\"fig-list\"><li><code>+fupDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li><li><code>+syncDataIDList: PositiveInteger [0..16] {ordered}</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als strukturelles Metamodell-Klassendiagramm bildet die Darstellung keine dynamischen Abläufe oder Nachrichtensequenzen ab. Sie definiert die statischen Konfigurationsstrukturen für die Laufzeitsynchronisation von Zeitnachrichten (SYNC, FUP) über CAN-Netzwerke, einschließlich Entprellung (<code>debounceTime</code>) und Timeout-Überwachung (<code>syncLossTimeout</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation ist normativ verbindlich:</p>\n<ul class=\"fig-list\"><li>Die Absicherung und Plausibilisierung der Zeitinformation nutzt Parameter wie <code>icvFreshnessValueId</code> für die Integritäts- und Frischeprüfung (SecOC / ICV) sowie <code>maxProgressionMismatchThreshold</code> für Schwellenwerte unzulässiger zeitlicher Abweichungen/Sprünge.\n</li><li>Die <code>domainId</code> unterliegt der AUTOSAR-Variantenbildung (<code>«atpVariation»</code>).\n</li><li>Für <code>CanGlobalTimeDomainProps</code> sind Daten-ID-Listen ausschließlich für SYNC- und FUP-Nachrichten spezifiziert.\n</li></ul>"}], "trans": [{"from": "FIG-70179fb886c56683", "to": "FIG-f0e1bcfd587df817", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Attribut <code>syncLossThreshold: TimeValue [0..1]</code> an <code>GlobalTimeDomain</code> entfernt.\n</li><li>Rollenname der Komposition von <code>GlobalTimeDomain</code> zu <code>AbstractGlobalTimeDomainProps</code> von <code>+globalTimeDomainProps</code> in <code>+globalTimeDomainProperty</code> umbenannt und mit Stereotyp <code>«atpVariation»</code> versehen.\n</li><li>Rekursive Assoziation von <code>GlobalTimeDomain</code> von <code>+subDomain 0..*</code> in <code>+globalTimeSubDomain 0..*</code> umbenannt und mit Stereotyp <code>«atpVariation»</code> versehen.\n</li></ul>"}, {"from": "FIG-f0e1bcfd587df817", "to": "FIG-547a8063ef0a4070", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-547a8063ef0a4070", "to": "FIG-476442918a3844eb", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Klasse <code>NetworkSegmentIdentification</code> mit Attribut <code>+networkSegmentId: PositiveInteger [0..1]</code> neu eingeführt.\n</li><li>Komposition von <code>GlobalTimeDomain</code> zu <code>NetworkSegmentIdentification</code> über Rolle <code>+networkSegmentId</code> mit Kardinalität <code>0..1</code> ergänzt.\n</li></ul>"}, {"from": "FIG-476442918a3844eb", "to": "FIG-6c5ce82ff231e827", "fr": "R20-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Stereotyp an Assoziationsende <code>+globalTimeSubDomain</code> von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code> erweitert.\n</li><li>Stereotyp an Kompositionsende <code>+globalTimeDomainProperty</code> von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code> erweitert.\n</li></ul>"}, {"from": "FIG-6c5ce82ff231e827", "to": "FIG-54e90da8e3bd05b4", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Stereotyp bzw. Supertyp <code>UploadableDesignElement</code> an <code>GlobalTimeDomain</code> ergänzt.\n</li><li>Multiplizität des Attributs <code>domainId</code> in <code>GlobalTimeDomain</code> von obligatorisch (<code>1</code>) auf optional geändert (<code>PositiveInteger [0..1]</code>).\n</li></ul>"}, {"from": "FIG-54e90da8e3bd05b4", "to": "FIG-7ee3e6dec7f699b0", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Attribute <code>+icvFreshnessValueId: PositiveInteger [0..1]</code> und <code>+maxProgressionMismatchThreshold: TimeValue [0..1]</code> in <code>GlobalTimeDomain</code> ergänzt.\n</li><li>Rekursive Assoziation <code>+offsetTimeDomain 0..1</code> an <code>GlobalTimeDomain</code> entfernt.\n</li></ul>"}, {"from": "FIG-7ee3e6dec7f699b0", "to": "FIG-d93ebfa1fdf11536", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>CanGlobalTimeDomainProps</code>: Die Attribute <code>ofnsDataIDList: PositiveInteger [0..16] {ordered}</code> und <code>ofsDataIDList: PositiveInteger [0..16] {ordered}</code> wurden entfernt.\n</li><li><code>GlobalTimeDomain</code>: Das Attribut <code>domainId: PositiveInteger [0..1]</code> ist mit dem Stereotyp <code>«atpVariation»</code> versehen.\n</li></ul>"}]};
